using System.Collections.Generic;
using UnityEngine;

namespace RH
{
    /// <summary>
    /// The Blender-made models in Resources/Models (generated by Tools/blender/build_models.py).
    /// Their material slots are named (body, trim, dark, screen...) and swapped at spawn time for
    /// the game's own shaders, so colours can vary per use: a unit's chassis colour, a PDU's feed.
    /// </summary>
    public static class Models
    {
        static readonly Dictionary<string, GameObject> prefabs = new Dictionary<string, GameObject>();

        public static GameObject Prefab(string name)
        {
            if (!prefabs.TryGetValue(name, out var p))
            {
                p = Resources.Load<GameObject>("Models/" + name);
                if (p == null) Debug.LogWarning("Missing model " + name);
                prefabs[name] = p;
            }
            return p;
        }

        /// <summary>Per-spawn material overrides, by slot name.</summary>
        public class Palette
        {
            readonly Dictionary<string, Material> map = new Dictionary<string, Material>();
            public Palette Set(string slot, Material m) { map[slot] = m; return this; }
            public Material Get(string slot) => map.TryGetValue(slot, out var m) ? m : null;
        }

        public static Palette With(string slot, Material m) => new Palette().Set(slot, m);

        /// <summary>A rack unit's palette: its chassis colour and a lighter front bezel.</summary>
        public static Palette Unit(DevDef def) =>
            new Palette().Set("body", Mats.Lit(def.color, 0.35f, 0.3f)).Set("bezel", Mats.Lit(def.color * 1.6f, 0.5f, 0.2f));

        /// <summary>The game's material for a slot name.</summary>
        public static Material Default(string slot) => slot switch
        {
            "body" => Mats.Lit(new Color(0.17f, 0.19f, 0.23f), 0.35f, 0.3f),
            "bezel" => Mats.Lit(new Color(0.27f, 0.3f, 0.36f), 0.5f, 0.2f),
            "trim" => Mats.Lit(new Color(0.6f, 0.62f, 0.66f), 0.5f, 0.7f),
            "steel" => Mats.Lit(new Color(0.3f, 0.36f, 0.45f), 0.3f, 0.5f),
            "dark" => Mats.Lit(new Color(0.03f, 0.03f, 0.035f), 0.2f),
            "rubber" => Mats.Lit(new Color(0.07f, 0.07f, 0.07f), 0.1f),
            "label" => Mats.Lit(new Color(0.9f, 0.9f, 0.86f), 0.2f),
            "screen" => Mats.Glow(new Color(0.2f, 0.55f, 1f), 1.4f),
            "lcd" => Mats.Glow(new Color(0.3f, 0.9f, 0.5f), 1.5f),
            "sled" => Mats.Lit(new Color(0.55f, 0.57f, 0.6f), 0.4f, 0.5f),
            "feed" => Mats.Lit(new Color(0.55f, 0.12f, 0.1f), 0.3f, 0.3f),
            "cardboard" => Mats.Lit(new Color(0.7f, 0.55f, 0.35f), 0.1f),
            "tape" => Mats.Lit(new Color(0.85f, 0.75f, 0.55f), 0.4f),
            "wood" => Mats.Lit(new Color(0.55f, 0.42f, 0.25f), 0.2f),
            "plastic" => Mats.Lit(new Color(0.15f, 0.35f, 0.6f), 0.4f),
            "red" => Mats.Lit(new Color(0.5f, 0.12f, 0.08f), 0.3f, 0.3f),
            "yellow" => Mats.Lit(new Color(0.85f, 0.7f, 0.15f), 0.3f, 0.4f),
            "pcb" => Mats.Lit(new Color(0.08f, 0.3f, 0.15f), 0.4f),
            "alu" => Mats.Lit(new Color(0.72f, 0.74f, 0.78f), 0.5f, 0.8f),
            "gold" => Mats.Lit(new Color(0.85f, 0.7f, 0.3f), 0.6f, 0.9f),
            "chip" => Mats.Lit(new Color(0.06f, 0.06f, 0.07f), 0.5f),
            "fabric" => Mats.Lit(new Color(0.12f, 0.13f, 0.16f), 0.05f),
            "diffuser" => Mats.Glow(new Color(0.95f, 0.98f, 1f), 2.5f),
            "fiber" => Mats.Unlit(new Color(0.95f, 0.78f, 0.15f)),
            "blue" => Mats.Lit(new Color(0.15f, 0.3f, 0.8f), 0.4f),
            "port" => Mats.Lit(new Color(0.25f, 0.27f, 0.3f), 0.3f),
            "glass" => Mats.Lit(new Color(0.3f, 0.36f, 0.42f), 0.8f),
            _ => Mats.Lit(new Color(0.5f, 0.5f, 0.5f)),
        };

        /// <summary>Instantiate a model under a parent, with its materials swapped for the game's.</summary>
        public static GameObject Spawn(string name, Transform parent, Vector3 localPos, Quaternion? localRot = null, Palette palette = null,
                                       bool collider = false, Vector3? scale = null, bool shadows = true)
        {
            var prefab = Prefab(name);
            GameObject g = prefab != null ? Object.Instantiate(prefab, parent, false) : new GameObject(name);
            g.name = name;
            var t = g.transform;
            t.localPosition = localPos;
            t.localRotation = localRot ?? Quaternion.identity;
            t.localScale = scale ?? Vector3.one;
            foreach (var r in g.GetComponentsInChildren<Renderer>(true))
            {
                var mats = r.sharedMaterials;
                for (int i = 0; i < mats.Length; i++)
                {
                    string slot = mats[i] != null ? mats[i].name.Replace(" (Instance)", "") : "";
                    mats[i] = palette?.Get(slot) ?? Default(slot);
                }
                r.sharedMaterials = mats;
                r.shadowCastingMode = shadows ? UnityEngine.Rendering.ShadowCastingMode.On : UnityEngine.Rendering.ShadowCastingMode.Off;
            }
            if (collider) FitCollider(g);
            return g;
        }

        /// <summary>Hide or show a named part of a spawned model (e.g. a unit's "Bays" while a drive is swapped).</summary>
        public static void ShowPart(GameObject g, string part, bool on)
        {
            var c = g.transform.Find(part);
            if (c != null) c.gameObject.SetActive(on);
        }

        /// <summary>Bounds of all the model's meshes, in its own local space.</summary>
        public static Bounds LocalBounds(GameObject g)
        {
            var inv = g.transform.worldToLocalMatrix;
            bool any = false;
            var b = new Bounds();
            foreach (var mf in g.GetComponentsInChildren<MeshFilter>())
            {
                if (mf.sharedMesh == null) continue;
                var mb = mf.sharedMesh.bounds;
                var m = inv * mf.transform.localToWorldMatrix;
                for (int i = 0; i < 8; i++)
                {
                    var c = mb.center + Vector3.Scale(mb.extents, new Vector3((i & 1) == 0 ? -1 : 1, (i & 2) == 0 ? -1 : 1, (i & 4) == 0 ? -1 : 1));
                    var p = m.MultiplyPoint3x4(c);
                    if (!any) { b = new Bounds(p, Vector3.zero); any = true; }
                    else b.Encapsulate(p);
                }
            }
            return b;
        }

        /// <summary>A box collider around the whole model.</summary>
        public static BoxCollider FitCollider(GameObject g)
        {
            var b = LocalBounds(g);
            var c = g.GetComponent<BoxCollider>();
            if (c == null) c = g.AddComponent<BoxCollider>();
            c.center = b.center;
            c.size = Vector3.Max(b.size, Vector3.one * 0.02f);
            return c;
        }

        // ================================================================ which model goes with what
        public static string For(DevDef def) => def.kind == DevKind.Tool ? "crash_cart" : def.id;
        public static string Psu(DevDef def) => def.heightU >= 4 ? "psu_4u" : def.heightU >= 2 ? "psu_2u" : "psu_1u";
        public static string Sled(DevDef def) => "sled_" + def.id;
        public static string Open(DevDef def) => def.heightU >= 2 ? "open_srv2u" : "open_srv1u";
        public static string Crate(DevDef def) => def.heightU >= 4 ? "crate_4u" : def.heightU >= 2 ? "crate_2u" : "crate_1u";
        public static string Carton(DevDef def) => def.heightU >= 2 ? "carton_2u" : "carton_1u";
    }
}
